Reported-by: Xiao Yang <yangx.jy@cn.fujitsu.com>
Reviewed-by: Xiao Yang <yangx.jy@cn.fujitsu.com>
Reviewed-by: Joel Fernandes <joel@joelfernandes.org>
Signed-off-by: Steven Rostedt (VMware) <rostedt@goodmis.org>

Here is the root cause:
The bug occurs because the preempt delay kernel thread may still be executing when the module is removed, leading to a situation where the thread attempts to run code that has already been unloaded, potentially causing a kernel crash. This happens particularly on slower machines where the timing of module removal and thread execution can overlap.

Here is the patch:

 static int preemptirq_delay_run(void *data)
 {
 	int i;
 	int s = MIN(burst_size, NR_TEST_FUNCS);

 	for (i = 0; i < s; i++)
 		(testfuncs[i])(i);
+
+	set_current_state(TASK_INTERRUPTIBLE);
+	while (!kthread_should_stop()) {
+		schedule();
+		set_current_state(TASK_INTERRUPTIBLE);
+	}
+
+	__set_current_state(TASK_RUNNING);
+
 	return 0;
 }

-static struct task_struct *preemptirq_start_test(void)
+static int preemptirq_run_test(void)
 {
+	struct task_struct *task;
+
 	char task_name[50];

 	snprintf(task_name, sizeof(task_name), "%s_test", test_mode);
-	return kthread_run(preemptirq_delay_run, NULL, task_name);
+	task =  kthread_run(preemptirq_delay_run, NULL, task_name);
+	if (IS_ERR(task))
+		return PTR_ERR(task);
+	if (task)
+		kthread_stop(task);
+	return 0;
 }


 static ssize_t trigger_store(struct kobject *kobj, struct kobj_attribute *attr,
 			 const char *buf, size_t count)
 {
-	preemptirq_start_test();
+	ssize_t ret;
+
+	ret = preemptirq_run_test();
+	if (ret)
+		return ret;
 	return count;
 }


 static int __init preemptirq_delay_init(void)
 {
-	struct task_struct *test_task;
 	int retval;

-	test_task = preemptirq_start_test();
-	retval = PTR_ERR_OR_ZERO(test_task);
+	retval = preemptirq_run_test();
 	if (retval != 0)
 		return retval;

 	preemptirq_delay_kobj = kobject_create_and_add("preemptirq_delay_test",
 						       kernel_kobj);
 	if (!preemptirq_delay_kobj)
 		return -ENOMEM;

 	retval = sysfs_create_group(preemptirq_delay_kobj, &attr_group);
 	if (retval)
 		kobject_put(preemptirq_delay_kobj);

 	return retval;
 }



